import { PopoverProps } from '@arco-design/web-react/es';
import { CSSProperties, HTMLAttributes, ReactNode } from 'react';
export interface IFormItemProps extends Omit<HTMLAttributes<any>, 'className'> {
    style?: CSSProperties;
    className?: string | string[];
    prefixCls?: string;
    /**
     * @zh 标签的文本
     * @en Label text
     */
    label?: ReactNode;
    /**
     * @zh label 的样式，如果传入了 width，优先级会高于 LabelCol 和 labelWidth
     */
    labelStyle?: CSSProperties;
    /**
     * @zh label 的宽度
     */
    labelWidth?: string | number;
    /**
     * @zh grid 布局 label 所占比格数
     * @en grid
     * @defaultValue 5
     */
    labelCol?: number;
    /**
     * @zh 标签换⾏，否则出现省略号，hover 有 tooltip
     */
    labelWrap?: boolean;
    /**
     * @zh
     * 组件容器样式
     */
    controlChildStyle?: CSSProperties;
    /**
     * @zh wrapper 的样式，如果传入了 width，优先级会高于 wrapperCol span
     */
    wrapperStyle?: CSSProperties;
    /**
     * @zh wrapper 的宽度
     */
    wrapperWidth?: string | number;
    /**
     * @zh  wrapper 所占栅格数
     * @en
     * @defaultValue 19
     */
    wrapperCol?: number;
    /**
     * @zh 是否显示标签后的一个冒号
     * @en Whether to add a colon after label
     */
    colon?: boolean;
    /**
     * @zh
     * 是否必选，会在 `label` 标签前显示加重红色符号，如果这里不设置，会从 rules 中寻找是否是 required
     * @en
     * Whether The FormItem is Required, Will display an red symbol in front of the `label` label.
     * If it is not set here, it will look for `required` from the rules
     */
    required?: boolean;
    /**
     * @zh
     * 当不是必选时，label 是否要对齐
     */
    requiredAlign?: boolean;
    /**
     * @zh 额外的提示内容。
     * @en Additional hint content.
     */
    extra?: ReactNode;
    /**
     * @zh 校验状态
     * @en Validate status
     */
    validateStatus?: 'success' | 'warning' | 'error' | 'validating';
    /**
     * @zh 是否显示校验图标，配置 validateStatus 使用。
     * @en Whether to show the verification icon, configure `validateStatus` to use.
     */
    hasFeedback?: boolean;
    /**
     * @zh 自定义校验文案
     * @en Custom help text
     */
    help?: ReactNode;
    /**
     * @zh 校验样式
     */
    helpLayout?: 'popover' | 'normal';
    /**
     * @zh hover 到组件上的提示
     * 优先级高于 helpLayout popover，如果传入则展示该错误
     * 如果使用了 helperTips ，注意!!! 需要和 rules 返回的错误信息一一对应
     */
    controlPopover?: PopoverProps & {
        helperTips?: string[];
    };
    /**
     * @zh 校验信息
     * 原始的校验信息，helper 用于展示
     * 目前只考虑错误
     */
    validateInfo?: {
        errors?: string[];
    };
    /**
     * @zh helpLayout 为 popover 弹出框挂载的节点
     * @en
     */
    getPopupContainer?: (node: HTMLElement) => Element;
    /**
     * @zh 标签的文本对齐方式，优先级高于 `Form`
     * @en Text alignment of `label`
     * @defaultValue right
     */
    labelAlign?: 'left' | 'right';
    layout?: 'horizontal' | 'vertical';
    /**
     * @zh 是否在 required 的时候显示加重的红色星号，设置 position 可选择将星号置于 label 前/后
     * @en Whether show red symbol when item is required，Set position props, you can choose to place the symbol before/after the label
     * @defaultValue true
     * @version `position` in 2.24.0
     */
    requiredSymbol?: boolean | {
        position: 'start' | 'end';
    };
    /**
     * @zh 不同尺寸。
     * @en size of form
     */
    size?: 'mini' | 'small' | 'default' | 'large';
    /**
     * @zh 问号提示
     */
    tooltip?: PopoverProps & {
        tooltipIcon?: ReactNode;
        tooltipLayout?: 'icon' | 'text';
        customRender?: () => ReactNode;
    };
    /**
     * @zh 前缀
     */
    addonBefore?: ReactNode;
    /**
     * @zh 后缀
     */
    addonAfter?: ReactNode;
    /**
     * @zh 栅格
     */
    gridSpan?: number;
    /**
     * @zh 是否有内嵌 FormItem
     * 如果有内嵌 FormItem，则不使用 ConfigProvider 透传属性，子 FormItem 本身去获取
     */
    hasInnerFormItem?: boolean;
    /**
     * @zh formItem 组件的 value
     */
    wrapperedComponentValue?: any;
}
export interface IFormItemLabelProps extends Pick<IFormItemProps, 'label' | 'requiredSymbol' | 'required' | 'tooltip' | 'labelAlign' | 'labelWrap' | 'labelStyle' | 'labelCol' | 'layout'> {
    showColon: boolean;
    enableCol?: boolean;
    requiredAlign?: boolean;
}
